GROUPS = [
 dict(id='LEX-B2-01',title='Explicar dados e limites de uma conclusão',after='B2-06',words=['back up','account for','point to','bias','sample','outcome','percentage point'],situation='A recebe levantamento fictício: duas consultas com 20 respondentes cada, aprovação de 40% na primeira e 50% na segunda; não se sabe se são as mesmas pessoas. Só usuários da manhã foram convidados. B recebe manchete “A cidade inteira passou a apoiar o plano; a melhora comprova efeito da campanha”. Comparem bases, amplitude e hipótese causal. Definam como outcome pretendido maior participação, mas há apenas opinião coletada, sem contagem de presença. Redijam correção e duas perguntas para investigação. Dividam o pacote em dois encontros se sete alvos dificultarem uso natural.',result='Support rose by ten percentage points in these samples; isso não prova mudança das mesmas pessoas. The sample excludes evening users and may contain selection bias. The figures do not back up a claim about the entire city. Comments may point to interest, but they do not establish attendance. We cannot tell what accounts for the difference. Increased participation is an intended outcome, not a measured one. Não concluir que campanha causou aumento.',phon='Distinguir TEN percentage POINTS de TWENTY-FIVE per cent relative increase para 40→50. Priorizar nome da medida e denominador; não exigir cálculo rápido em interação.',pitfall='Aritmética não substitui análise da amostra. Account for tem aqui sentido explicar; o sentido representar proporção precisa de ensino adicional antes de ser cobrado.'),
 dict(id='LEX-B2-02',title='Combinar entrega e transferência de responsabilidade',after='B2-01',words=['scope','deliverable','trade-off','hand over','provided that'],situation='A cliente quer guia de duas páginas até sexta. Escopo inclui redação e revisão, exclui tradução. B equipe pode entregar sexta desde que aprove rascunho terça. Mais exemplos exigem quatro páginas e revisão adicional; não há prazo dessa alternativa confirmado. Lee assumirá manutenção após reunião de transferência, ainda não marcada. Negociem sem transformar envio de arquivo em transferência já aceita.',result='The deliverable is a two-page guide. Translation is outside the scope. We can deliver on Friday provided that the draft is approved by Tuesday. There is a trade-off between detail and the current format. We need to arrange when to hand the guide over to Lee. Estado da entrega e aceitação da responsabilidade devem ser confirmados separadamente.',phon='Marque pausa antes de provided that; ouvinte repete entrega e condição. Pratique hand it OVER to LEE com objeto pronominal no meio.',pitfall='Explicar deliverable em linguagem comum para destinatário leigo. Não inventar inevitabilidade de escolha binária: mais exemplos podem virar anexo se for negociado com prazo próprio.'),
 dict(id='LEX-B2-03',title='Rever um problema sem inventar uma causa única',after='B2-03',words=['rule out','look back','contribute to'],situation='A tem registro: encontro começou 18h, cinco participantes avisaram atraso de ônibus, outros três faltaram sem mensagem. B lê análise que atribui todas as oito ausências iniciais ao ônibus. Atrasados chegaram depois; faltantes não. Expliquem o que transporte pode ter contribuído para causar, o que não pode ser descartado e o que falta saber. Retrospectivamente proponham confirmar horários de chegada.',result='Looking back, we needed clearer arrival information. Transport delays contributed to the five reported late arrivals; não justificam automaticamente três faltas sem mensagem. We can’t rule out transport problems for the others, but we don’t know. Não descartar não equivale a confirmar. As cinco chegadas posteriores não são faltas finais.',phon='Ouça can / can’t rule out em frases completas e peça que colega reformule “possível, não confirmado” ou “descartado” conforme caso.',pitfall='Contribute to preserva possibilidade de causas adicionais. A fonte confirma atrasos relatados por cinco pessoas, não investigação independente de toda logística.'),
 dict(id='LEX-B2-04',title='Separar inscrição, elegibilidade e escolha de participação',after='B2-04',words=['opt out','sign up','pending','eligible'],situation='Oficina fictícia: 20 inscritos, 12 presentes. Desconto disponível para membros; Nara é membro, pedido ainda em análise. Gravação opcional separada da oficina: dois presentes escolheram não ser gravados e permaneceram na atividade. A recepção precisa explicar estados a B, que confunde desconto possível com recebido e opt out com expulsão.',result='Twenty people signed up; twelve attended. Nara is eligible for the discount, but approval is pending. Two participants opted out of recording and stayed in the workshop. Não chamar os oito ausentes de expulsos nem marcar desconto concedido.',phon='Organize números em blocos: TWENTY signed up / TWELVE attended / TWO opted out OF RECORDING. Ouvinte restitui atividade específica de cada número.',pitfall='Usar regras fictícias; não transformar elegibilidade deste cartão em promessa real de desconto. Opt out of pede complemento que delimita participação recusada.'),
 dict(id='LEX-B2-05',title='Comparar enquadramentos de uma notícia',after='B2-06',words=['framing','misleading','underlying','whereas'],situation='A tem tabela: visitação ficou 100 nos dois meses; custo direto caiu de 200 para 180 créditos; custo indireto não registrado. B tem manchete “Menor custo por visitante resolve orçamento inteiro”. Comparem o que tabela sustenta e o que omite. Produzam manchetes alternativas e peçam dados faltantes, sem atribuir intenção ao autor.',result='Direct costs fell, whereas attendance stayed stable. The underlying figures cover direct costs only. The framing suggests a complete budget solution, which may be misleading because overhead costs are absent. Alternative: Direct costs fall while attendance remains unchanged. Não inferir custo total ou saldo sem rubricas ausentes.',phon='Use pausa antes de whereas para marcar contraste, não simultaneidade temporal. O parceiro aponta as duas medidas comparadas.',pitfall='Misleading descreve possível efeito da apresentação; não chamar qualquer enquadramento de fraude. Pode retomar overhead com glossário, sem avaliá-lo antes da sequência própria.'),
 dict(id='LEX-B2-06',title='Responder com clareza e cortesia sem prometer demais',after='B2-04',words=['abrupt','get back to','draft','reassure'],situation='A recebe mensagem “Send the final version now”. Documento é só rascunho; horário de reunião confirmado às 15h, equipamento pendente. B pode retornar contato amanhã com atualização, não garantir decisão. Reescrevam a solicitação e a resposta mantendo urgência se houver prazo, mas sem chamar rascunho de final ou tranquilizar sobre equipamento não conferido.',result='The request may sound abrupt in this context. Could you send the current draft by three? B: I can reassure you that the meeting time is confirmed. The equipment is still pending. I’ll get back to you tomorrow with an update. Não prometer versão final se ainda em revisão.',phon='Pratique contraste CURRENT DRAFT / FINAL VERSION e tomorrow WITH AN UPDATE. Ouvinte distingue prazo de contato de prazo de solução.',pitfall='Cortesia depende de contexto. Não usar reassure como fórmula que apaga incerteza nem get back to como promessa implícita de conclusão.'),
 dict(id='LEX-B2-07',title='Interpretar uma história mantendo perspectiva e evidência',after='B2-05',words=['draw on','leave out','narrator','interpretation'],situation='Microficção autoral: “I saw Jo close the window and assumed she wanted me to leave. I left before she returned. Later, her note said the rain had reached the books.” Nota autoral fictícia informa que conto se baseia em lembranças de tempestades, mas não relata um evento real. A propõe rejeição como leitura; B aponta perspectiva limitada e informação posterior. Escrevam duas interpretações, indicando o que cada uma usa ou omite.',result='The story draws on memories but remains fiction. The narrator initially interprets the closed window as rejection. That interpretation leaves out the later note about rain. The note supports a practical reason, but does not reveal every feeling Jo had. Narrator não é automaticamente autor; perspectiva inicial não prova intenção.',phon='Marque I ASSUMED versus her NOTE SAID. Ouvinte identifica a fonte de cada afirmação. Pratique leaves IT out com pronome entre verbo e partícula.',pitfall='Não impor uma interpretação psicológica única. Exigir apoio textual e limites; toda narrativa e nota foram criadas para este exercício.'),
 dict(id='LEX-B2-08',title='Propor uma ação pública e acompanhar sua viabilidade',after='B2-07',words=['put forward','feasible','follow up'],situation='A propõe encontro mensal de bairro. Sala comporta 20 e orçamento cobre aluguel; há 18 interessados, mas responsável por abrir sala não confirmou e não há acordo sobre horário. B escreve “Tudo está aprovado”. Reformulem proposta, viabilidade parcial e próximo acompanhamento. Identifiquem quem deve responder sem supor votação.',result='We put forward a proposal for a monthly meeting. It appears feasible in terms of space and the stated room budget, but staffing and timing remain unresolved. We’ll follow up on access and availability. Proposta não aprovada; viabilidade financeira limitada ao aluguel conhecido, não todo custo possível.',phon='Destaque feasible IN TERMS OF SPACE; complemento limita a avaliação. O colega enumera pendências após ouvir.',pitfall='Follow up não significa resolver. Put forward a proposal pode ser reformulado como propose para público geral, registrando alvo ainda não observado se não usado.'),
 dict(id='LEX-B2-09',title='Discutir participação digital com limites claros',after='B2-08',words=['privacy','accessibility'],situation='Grupo quer divulgar relato de oficina. Há nomes e imagens identificáveis; autorização de divulgação ainda não foi solicitada. Vídeo tem legendas, mas instruções pequenas e confusas. A sugere que “com legendas e sem nomes, tudo está resolvido”. B aponta imagens identificáveis e outras barreiras. Proponham rascunho de mudanças, sem publicação real nem alegação de conformidade.',result='Removing names alone may not protect privacy if faces remain identifiable. Captions improve one aspect of accessibility, but the instructions still need clearer presentation. We should clarify participation and publication arrangements before sharing the material. Não prometer anonimato, acessibilidade universal ou conformidade legal.',phon='Peça ao ouvinte separar privacy de accessibility pelas consequências no cenário, não só pela pronúncia isolada. Use exemplos completos.',pitfall='Ensino de língua, não avaliação jurídica ou auditoria de acessibilidade. Aceitar identificação de limites e pergunta pertinente, sem exigir conhecimento técnico externo.'),
 dict(id='LEX-B2-10',title='Comparar custo total e alegações de sustentabilidade',after='B2-06',words=['sustainable','emissions','overhead','value for money'],situation='A compara dois fornecedores fictícios: X cobra 20 por serviço e transporte incluído; Y cobra 18 e transporte 5. Ambos omitem custos administrativos do projeto. X anuncia meta de reduzir emissões, sem medição. Receita mensal do projeto é incerta. B precisa recomendar comparação de custo e pedir dados, sem transformar menor custo conhecido em sustentabilidade geral.',result='For the stated need, X costs twenty and Y twenty-three, so X may offer better value for money if services are otherwise suitable. The project estimate still excludes overhead costs. Reducing emissions is X’s goal, not a measured result. Financial sustainability depends on recurring costs and funding; nenhuma dimensão está comprovada apenas pelo preço.',phon='O destinatário restitui eighteen PLUS FIVE e twenty INCLUDING TRANSPORT. Faça contraste AIMS TO reduce / HAS reduced sem afirmar segundo caso.',pitfall='Não usar sustainable sem dimensão. Comparação fictícia de linguagem e aritmética, não recomendação financeira ou ambiental real.'),
 dict(id='LEX-B2-11',title='Reparar um desacordo e estabelecer limites',after='B2-08',words=['let down','make up','take for granted','set a boundary','resentment','supportive'],situation='A prometeu revisar texto sexta, esqueceu e não avisou. B relata decepção e ressentimento porque A presumiu que B sempre compensaria atrasos. B quer manter amizade, mas não responderá mensagens de trabalho após 20h. A reconhece o ocorrido, propõe reparação e pede fazer as pazes. B pode aceitar, pedir tempo ou recusar conversa naquele momento. Não exigir exposição de história pessoal; use personagens.',result='A: I’m sorry I let you down. I took your help for granted. I’d like to make up, but I understand if you need time. B: I feel resentment about the repeated extra work. I want to be supportive, but I need to set a boundary: I won’t answer work messages after eight. Reconciliação não pode ser registrada antes da resposta de B; apoio não exige concordar nem abandonar limite.',phon='Pratique let YOU down e took your HELP for granted para localizar impacto. Use pausas ao formular limite; não avaliar emoção pela imitação de um sotaque ou tom único.',pitfall='Vocabulário relacional, não terapia nem diagnóstico. Resentment é sentimento atribuído ao personagem. Make up neste pacote é reconciliação; outros sentidos ficam fora da avaliação.'),
 dict(id='LEX-B2-12',title='Planejar uma refeição e descrever preferências',after='B2-06',words=['cut down on','run out of','leftovers','use up','bland','filling'],situation='A e B planejam jantar fictício. Arroz acabou, há farinha suficiente para duas porções e legumes para duas. A sugere usar toda farinha para evitar compra adicional; B quer reduzir compras desnecessárias, não eliminar alimentação. Há sobras no frigorífico com data desconhecida: descrevam sem concluir que podem ser consumidas. Após refeição fictícia de legumes e massa, A a considera pouco marcante de sabor, B a considera saciante. Negociem próxima compra respeitando preferências.',result='We’ve run out of rice. We could use up the flour and cut down on unnecessary purchases. There are leftovers, but we don’t know when they were prepared. A: I found the meal a little bland. B: I found it filling. Preferências são percepções; não inferir valor nutricional nem segurança das sobras. Modelo não prescreve consumo das sobras.',phon='Contraste run OUT OF rice com still HAVE flour. O parceiro faz lista do que acabou e do que permanece. Pratique use IT up com pronome.',pitfall='Filling é adjetivo nesta sequência, não recheio. Não avaliar conhecimento culinário ou médico. Explorar como bland/filling podem coexistir, sem tratá-los como antônimos.'),
 dict(id='LEX-B2-13',title='Descrever moradia e esclarecer documentos',after='B2-04',words=['leak','damp','wear and tear','tenancy','deposit','notice'],situation='Documento fictício: tenancy começa 1 de junho; rent 600, deposit separado de 600; requer aviso escrito para saída, sem prazo especificado no excerto. A percebe gotejamento sob pia e parede úmida depois de chuva; não sabe causa. Tapete apresenta desgaste e rasgo cuja origem não está registrada. B recebe pedido de verificação. A pretende sair dia 30 e deu aviso ontem; não presumam validade jurídica nem desconto da garantia.',result='There seems to be a leak under the sink, and the wall feels damp. The carpet shows wear and tear, but the cause of the tear is unknown. The tenancy starts on the first of June. The document lists rent and a separate deposit. I gave notice yesterday and plan to leave on the thirtieth. Could you clarify the notice requirements and arrange an inspection? Não afirmar reparo, devolução de garantia ou saída já realizados.',phon='Separar RENT e DEPOSIT ao ler valores iguais; ouvinte deve nomear duas rubricas. Distinguir descrição sensorial de hipótese de causa com pausas.',pitfall='Condições são apenas do excerto fictício. Não recomendar prazo legal nem atribuir responsabilidade financeira. Notice neste uso é aviso de saída; usos como perceber precisam de sequência própria.')
]

GROUPS += [{'id': 'LEX-B2-14',
  'title': 'Negociar apoio sem presumir capacidade ou intenção',
  'after': 'B2-08',
  'words': ['frustrated', 'overwhelmed', 'self-conscious', 'sympathetic', 'considerate', 'insensitive'],
  'situation': 'Nota fictícia: “Jo says she feels overwhelmed by six simultaneous requests, not by the '
               'difficulty of any one task. Repeated changes have left her frustrated. She also feels '
               'self-conscious about recording her voice. Her manager listens sympathetically but cannot '
               'move Friday’s external deadline.” Outra mensagem: Lee perguntou preferências e ofereceu '
               'repartir trabalho; Jo achou isso atencioso. Um comentário “You just need to try harder” foi '
               'percebido por Jo como insensível; autor não explicou intenção. A negocia prioridades, B '
               'sintetiza perspectivas em linguagem cuidadosa. Produza resposta de 120–160 palavras '
               'preservando limite de prazo e possibilidade de apoio.',
  'result': 'Jo feels overwhelmed by simultaneous volume and frustrated by changes; não prova incapacidade '
            'geral. She feels self-conscious about recording, not necessarily unable to speak. The manager '
            'is sympathetic but deadline remains. Lee’s offer was considered considerate. Jo found the other '
            'comment insensitive; intenção não estabelecida. Proposta possível: distribute tasks and agree '
            'priorities, mantendo aprovação da distribuição como etapa futura.',
  'phon': 'Use atribuição audível: JO FOUND it insensitive / the author’s intention is UNKNOWN. Parceiro '
          'distingue percepção, ação e intenção. Leitura neutra também pode comunicar com clareza.',
  'pitfall': 'Sympathetic não é tradução automática de simpático, e self-conscious não é mero '
             'autoconhecimento. Não exigir relato de vulnerabilidade real. Uma mensagem empática não garante '
             'solução de restrições materiais.'}]

GROUPS += [{'id': 'LEX-B2-15',
  'title': 'Negociar carga de trabalho e delegação',
  'after': 'B2-04',
  'words': ['workload', 'negotiate', 'compromise', 'delegate'],
  'situation': 'Equipe fictícia tem duas pessoas e seis relatórios, prazo sexta. Jo propõe negociar prazo; '
               'cliente aceita receber quatro relatórios sexta e dois segunda. Lee pode revisar dois, mas Jo '
               'mantém aprovação final. A representa Jo, B cliente ou Lee. Negociem escopo, prazo e '
               'responsabilidade; escrevam acordo distinguindo concessão aceita de proposta ainda aberta. No '
               'cartão alternativo, cliente ainda não respondeu: não reutilizar linguagem de acordo '
               'alcançado.',
  'result': 'The workload exceeds the original allocation in the scenario. They negotiated and reached a '
            'compromise: four reports Friday, two Monday. Jo delegated two reviews to Lee but kept final '
            'approval. Cartão alternativo: We are trying to negotiate; no compromise has been agreed yet. '
            'Delegação não significa conclusão das revisões nem transferência automática de toda '
            'responsabilidade.',
  'phon': 'Marque FOUR on Friday / TWO on Monday e REVIEW / FINAL APPROVAL. O parceiro devolve distribuição '
          'exata antes de fechar o acordo.',
  'pitfall': 'Não traduzir compromise por compromisso em todo contexto. O pacote não aconselha gestão real '
             'de pessoal; avalia clareza da negociação fictícia. Aceitar proposta diferente se dados e '
             'aceites forem atualizados explicitamente.'}]

GROUPS += [{'id': 'LEX-B2-16',
  'title': 'Sintetizar relatos ambientais com alcance limitado',
  'after': 'B2-06',
  'words': ['drought', 'flood', 'habitat', 'conserve'],
  'situation': 'Boletim fictício A informa seca prolongada na região Norte; não traz medidas de intensidade '
               'nem causa. Boletim B informa inundação na região Sul ontem, estrada fechada naquele momento; '
               'situação atual desconhecida. Uma campanha visa conservar água e outra proposta visa proteger '
               'habitat, mas não há medição de efeitos nem execução confirmada da proposta. A prepara '
               'síntese; B rejeita mensagem que mistura regiões e afirma sucesso das campanhas. Produzam '
               'versão com lugares, tempos e limites.',
  'result': 'The northern report describes a prolonged drought. The southern report describes a flood '
            'yesterday; current road access needs checking. The campaign encourages people to conserve '
            'water, but no reduction is measured. The proposal aims to protect habitat; implementation is '
            'unconfirmed. Não tratar seca e inundação como mesmo evento ou inferir causa global a partir dos '
            'cartões.',
  'phon': 'Destaque NORTH / SOUTH, YESTERDAY / NOW UNKNOWN e AIMS TO / HAS DONE. Destinatário organiza '
          'tabela de fonte, ocorrência e estado.',
  'pitfall': 'Os boletins são ficção de ensino, não aconselhamento ambiental ou alerta real. Nenhuma '
             'espécie, causa ou estimativa climática externa foi inventada. Nomear fenômeno não comprova seu '
             'mecanismo.'}]
